begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
-- Privileged fixture setup only. Every access assertion below switches to a real API role.
insert into auth.users(id, email) values
 ('10000000-0000-4000-8000-000000000001','a@example.test'),
 ('10000000-0000-4000-8000-000000000002','b@example.test'),
 ('10000000-0000-4000-8000-000000000003','removed@example.test');
insert into auth.sessions(id, user_id) values
 ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),
 ('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002'),
 ('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003');
insert into finance.profiles(id, display_name) values
 ('10000000-0000-4000-8000-000000000001','Synthetic A'),
 ('10000000-0000-4000-8000-000000000002','Synthetic B'),
 ('10000000-0000-4000-8000-000000000003','Synthetic removed');
insert into finance.households(id,name) values
 ('30000000-0000-4000-8000-000000000001','Household A'),
 ('30000000-0000-4000-8000-000000000002','Household B');
insert into finance.household_members(id, household_id, user_id, display_name, status) values
 ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A','ACTIVE'),
 ('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B','ACTIVE'),
 ('40000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003','Synthetic removed','REVOKED');

select ok((select bool_and(relrowsecurity) from pg_class where oid in ('finance.account_sources'::regclass,'finance.fx_evidence'::regclass)),'Source and FX evidence tables have RLS');
select ok(not exists(select 1 from information_schema.columns where table_schema='finance' and table_name='accounts' and column_name='manual_source_id'),'Account persistence no longer contains source identity');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","session_id":"20000000-0000-4000-8000-000000000001","role":"authenticated"}'::jsonb::text,true);
select is(api.create_account('{"account":{"id":"50000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","name":"Synthetic source review 1","ownership":{"kind":"HOUSEHOLD"},"type":"BANK","currency":"USD","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"70000000-0000-4000-8000-000000000001"}'::jsonb)->>'ok','true','Account creation atomically creates independent manual source');
select is(api.create_account('{"account":{"id":"50000000-0000-4000-8000-000000000002","householdId":"30000000-0000-4000-8000-000000000001","name":"Synthetic source review 2","ownership":{"kind":"HOUSEHOLD"},"type":"BANK","currency":"USD","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"70000000-0000-4000-8000-000000000002"}'::jsonb)->>'ok','true','Second account has its own manual source');
select is((select kind from finance.account_sources where id='70000000-0000-4000-8000-000000000001'),'MANUAL','Manual source mode lives on source relation');
select is((select authoritative_from::text from finance.account_sources where id='70000000-0000-4000-8000-000000000001'),'0001-01-01','Manual baseline has explicit authority');
select throws_ok($sql$insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','MANUAL','0001-01-01')$sql$,'23505',null,'Competing manual sources rejected');
select throws_ok($sql$insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','FILE_IMPORT','2026-10-02')$sql$,'42501',null,'Current client cannot appoint imported authority');
select throws_ok($sql$insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001','MANUAL','0001-01-01')$sql$,'42501',null,'Source creation across households rejected by RLS');
select throws_ok($sql$update finance.account_sources set authoritative_from='2026-10-02' where id='70000000-0000-4000-8000-000000000001'$sql$,'42501',null,'Client cannot rewrite authority');
select throws_ok($sql$delete from finance.account_sources where id='70000000-0000-4000-8000-000000000001'$sql$,'42501',null,'Client cannot delete source');
reset role;
insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','FILE_IMPORT','2026-10-02');
insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','LIVE_SYNC',null);
select throws_ok($sql$insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001','LIVE_SYNC',null)$sql$,'23503',null,'Household/account composite FK survives privileged setup');
select throws_ok($sql$insert into finance.account_sources(id,household_id,account_id,kind,authoritative_from) values('70000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','LIVE_SYNC','2026-10-02')$sql$,'23505',null,'Equal-date authorities cannot compete');
select throws_ok($sql$update finance.account_sources set account_id='50000000-0000-4000-8000-000000000002' where id='70000000-0000-4000-8000-000000000003'$sql$,'23514',null,'Source account identity immutable');
select throws_ok($sql$update finance.account_sources set authoritative_from='2026-10-03' where id='70000000-0000-4000-8000-000000000003'$sql$,'23514',null,'Published activation date immutable');
update finance.account_sources set authoritative_from='2026-10-05' where id='70000000-0000-4000-8000-000000000004';
select is((select authoritative_from::text from finance.account_sources where id='70000000-0000-4000-8000-000000000004'),'2026-10-05','Unappointed source can receive one activation');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","session_id":"20000000-0000-4000-8000-000000000001","role":"authenticated"}'::jsonb::text,true);
select is((select count(*)::text from finance.account_sources where account_id='50000000-0000-4000-8000-000000000001'),'3','One stable account supports manual import and live source identities');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":null}'::jsonb)->>'ok','true','Manual root observation accepted');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000002","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000003","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":null}'::jsonb)->>'ok','true','Independent source can observe same account and date');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000003","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','CONFLICT','Same-source duplicate root conflicts');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000003","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000001","note":"Synthetic review fixture","fx":null}'::jsonb)->>'ok','true','Correction remains within source lineage');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000004","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000001","note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','CONFLICT','Competing correction cannot replace same predecessor');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000004","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000003","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000003","note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','INVALID_INPUT','Correction cannot cross source');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000004","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-03","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000003","note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','INVALID_INPUT','Correction cannot cross date');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000004","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000002","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','INVALID_INPUT','Observation cannot borrow another account source');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000004","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000999","date":"2026-10-02","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":null}'::jsonb)->'error'->>'code','INVALID_INPUT','Unknown source cannot create observation');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000010","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000001","date":"2026-10-03","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"3.72","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"MANUAL","sourceId":"70000000-0000-4000-8000-000000000001"}}}'::jsonb)->>'ok','true','Historical FX evidence recorded');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000011","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000002","sourceId":"70000000-0000-4000-8000-000000000002","date":"2026-10-03","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic review fixture","fx":{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"3.72","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"MANUAL","sourceId":"70000000-0000-4000-8000-000000000001"}}}'::jsonb)->>'ok','true','Same FX identity and evidence reusable across accounts and sources');
select is((select count(*)::text from finance.fx_evidence where household_id='30000000-0000-4000-8000-000000000001'),'1','Shared FX reference has one immutable evidence record');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000012","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000002","sourceId":"70000000-0000-4000-8000-000000000002","date":"2026-10-03","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000011","note":"Synthetic review fixture","fx":{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"4","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"MANUAL","sourceId":"70000000-0000-4000-8000-000000000001"}}}'::jsonb)->'error'->>'code','INVALID_INPUT','Same FX identity cannot change rate');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000012","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000002","sourceId":"70000000-0000-4000-8000-000000000002","date":"2026-10-03","money":{"amount":"100","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000011","note":"Synthetic review fixture","fx":{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"3.72","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"FILE_IMPORT","sourceId":"70000000-0000-4000-8000-000000000003"}}}'::jsonb)->'error'->>'code','INVALID_INPUT','Same FX identity cannot change provenance');
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000012","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000002","sourceId":"70000000-0000-4000-8000-000000000002","date":"2026-10-03","money":{"amount":"101","currency":"USD"},"coverage":"COMPLETE","supersedesId":"60000000-0000-4000-8000-000000000011","note":"Synthetic review fixture","fx":{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"3.72","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"MANUAL","sourceId":"70000000-0000-4000-8000-000000000001"}}}'::jsonb)->>'ok','true','Correction can reuse unchanged historical rate');
select throws_ok($sql$update finance.fx_evidence set snapshot='{}' where id='80000000-0000-4000-8000-000000000001'$sql$,'42501',null,'Client cannot edit historical FX evidence');
select throws_ok($sql$insert into finance.fx_evidence(household_id,id,snapshot) values('30000000-0000-4000-8000-000000000002','80000000-0000-4000-8000-000000000001','{"id":"80000000-0000-4000-8000-000000000001","base":"USD","quote":"ILS","rate":"3.72","effectiveDate":"2026-10-03","recordedAt":"2026-10-01T12:00:00Z","origin":{"kind":"MANUAL","sourceId":"70000000-0000-4000-8000-000000000001"}}'::jsonb)$sql$,'42501',null,'FX evidence cannot cross household RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","session_id":"20000000-0000-4000-8000-000000000002","role":"authenticated"}'::jsonb::text,true);
select is((select count(*)::text from finance.account_sources),'0','Other household cannot see source identities');
select is((select count(*)::text from finance.fx_evidence),'0','Other household cannot see FX evidence');
select is(api.create_account('{"account":{"id":"50000000-0000-4000-8000-000000000020","householdId":"30000000-0000-4000-8000-000000000002","name":"Synthetic B source","ownership":{"kind":"HOUSEHOLD"},"type":"BANK","currency":"USD","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"70000000-0000-4000-8000-000000000001"}'::jsonb)->'error'->>'code','CONFLICT','Source identity cannot be reused by another household');
select is((select count(*)::text from finance.accounts),'0','Failed source creation rolls back account atomically');
select is(api.create_account('{"account":{"id":"50000000-0000-4000-8000-000000000020","householdId":"30000000-0000-4000-8000-000000000002","name":"Synthetic B source","ownership":{"kind":"HOUSEHOLD"},"type":"BANK","currency":"USD","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"70000000-0000-4000-8000-000000000020"}'::jsonb)->>'ok','true','Second household receives independent source');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","session_id":"20000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(api.record_balance('{"id":"60000000-0000-4000-8000-000000000090","householdId":"30000000-0000-4000-8000-000000000001","accountId":"50000000-0000-4000-8000-000000000001","sourceId":"70000000-0000-4000-8000-000000000020","date":"2026-10-04","money":{"amount":"10","currency":"USD"},"coverage":"COMPLETE","supersedesId":null,"note":"Synthetic foreign source","fx":null}'::jsonb)->'error'->>'code','INVALID_INPUT','Observation cannot reference another household source');
reset role;
select throws_ok($sql$update finance.fx_evidence set snapshot=jsonb_set(snapshot,'{rate}','"4"') where id='80000000-0000-4000-8000-000000000001'$sql$,'23514',null,'Historical evidence immutable even with privileged update');
select throws_ok($sql$delete from finance.account_sources where id='70000000-0000-4000-8000-000000000001'$sql$,'23503',null,'Referenced source deletion restricted');
select throws_ok($sql$delete from finance.fx_evidence where id='80000000-0000-4000-8000-000000000001'$sql$,'23503',null,'Referenced FX deletion restricted');
update finance.household_members set status='REVOKED' where id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","session_id":"20000000-0000-4000-8000-000000000001","role":"authenticated"}'::jsonb::text,true);
select is((select count(*)::text from finance.account_sources),'0','Revoked member cannot see sources with unchanged claims');
select is((select count(*)::text from finance.fx_evidence),'0','Revoked member cannot see FX evidence');
reset role;
set local role anon;
select throws_ok($sql$select * from finance.account_sources$sql$,'42501',null,'Anonymous source access denied');
select throws_ok($sql$select * from finance.fx_evidence$sql$,'42501',null,'Anonymous FX access denied');
reset role;
select * from finish();
rollback;
